def current_user(headers, tokens):
    auth = headers.get("authorization")
    if not auth:
        return {"status": 401}
    scheme, _, token = auth.partition(" ")
    if scheme.lower() != "bearer" or token not in tokens:
        return {"status": 401}
    return {"user": tokens[token]}

