def page_links(total, page, size, base):
    pages = max(1, -(-total // size))
    link = lambda n: f"{base}?page={n}&size={size}"
    return {"total": total,
            "next": link(page + 1) if page < pages else None,
            "prev": link(page - 1) if page > 1 else None}

